port.tfmBody:
// 그늘 띠 붓 방향(11/05 재연 님 결함 후보 2 — 탁자 그림자 띠에서 짙은 굵은 획이 사선으로 아래로 늘어진 빗금, OIL.slope): 3D 소스는 결 문턱(tfmE 1e-3)이 높아
// 부드러운 그림자 띠도 '결 없음'이라 기본 60도로 칠하고, 사선 획이 가로 띠를 가로질러 짙은 색을 끌고 내려간다. 결이 약한 곳의 기본 방향을
// 크게 흐린 원본(밉 5)의 밝기 등고선 쪽으로 — 그러데이션이 .08~.16 넘게 뚜렷한 곳(그림자 띠 가운데)만. 얼굴 음영(대개 .06 안팎)은 그대로 둬
// 10/22에 막은 얼굴 붓 방향 흔들림이 돌아오지 않게(정지 얼굴 반짝임 +15%, 낮은 문턱 .03~.08은 +44%)
if (uSlopeK > 0.) {
  vec2 tx = 32./vec2(textureSize(uGr, 0));
  float gx = lum(textureLod(uGr, vUV + vec2(tx.x, 0.), 5.).rgb) - lum(textureLod(uGr, vUV - vec2(tx.x, 0.), 5.).rgb);
  float gy = lum(textureLod(uGr, vUV + vec2(0., tx.y), 5.).rgb) - lum(textureLod(uGr, vUV - vec2(0., tx.y), 5.).rgb);
  float mg = length(vec2(gx, gy));
  if (mg > 1e-5) { vec2 tc = vec2(-gy, gx)/mg; d2 = mix(d2, vec2(tc.x*tc.x - tc.y*tc.y, 2.*tc.x*tc.y), uSlopeK*smoothstep(.08, .16, mg)); }
}

port.strokeStep:
// 눈·코 테 정리(11/02 재연 님 '눈 주위를 원형으로 둘러싼 잡티'): 중간 붓(굵기 27 · 길이 90px)이 눈 안에서 짙은 색을 집어 눈 밖으로 뻗고,
// 뒤 층에 대부분 덮인 뒤 남은 조각이 눈 둘레 고리 모양 잡티가 된다(영상에서는 그림마다 반짝여 테두리처럼 읽힘). 작은 검정 덩이 경계를 넘어
// 밝기가 .3 넘게 다른 곳으로 가는 획만 거기서 멈춘다(짙은 획이 밖으로 · 흰 획이 눈 안으로). 다른 자리 획은 그대로
if (uEyeK > 0.) { vec2 nq = (p + dcur*s)/uRes;
  if (max(blb(p/uRes), blb(nq)) > .3 && abs(lum(textureLod(uGrade, nq, .6).rgb) - lum(col)) > .3) break; }
if (uSpillK > 0. && uErrT <= 0. && spillTo((p + dcur*s)/uRes, col)) break;   // 경계 옆 번짐 띠(OIL.spill, 아래 spillTo)

port.strokeWidth:
float wv = W*.5*taper;                                         // 폭도: 옆 꼭짓점이 평평한 다른 색 바탕에 떨어지면 반씩(최대 ⅛까지) 줄인다
if (uSpillK > 0. && uErrT <= 0.) for (int k = 0; k < 3; k++) { if (!spillTo((p + nrm*side*wv)/uRes, col)) break; wv *= .5; }
p += nrm*side*wv;

port.strokeFns:
bool spillTo(vec2 q, vec3 col){
  vec3 g = textureLod(uGrade, q, 1.).rgb; if (distance(g, col) <= .04/uSpillK) return false;   // 값 1 = .04, 작을수록 문턱이 높아(0.5 = .08) 덜 멈춘다
  vec2 tq = 10./vec2(textureSize(uGrade, 0));
  return max(max(distance(textureLod(uGrade, q + vec2(tq.x, 0.), 1.).rgb, g), distance(textureLod(uGrade, q - vec2(tq.x, 0.), 1.).rgb, g)),
             max(distance(textureLod(uGrade, q + vec2(0., tq.y), 1.).rgb, g), distance(textureLod(uGrade, q - vec2(0., tq.y), 1.).rgb, g))) < .02;
}

port.finishBody:
// 눈·코 테 정리(11/02 고객 '눈두덩이에 검은 뜬 테두리', OIL.eye): 굵은 붓은 흐린 원본(밉 1.4~3.8)에서 색을 집어 형태를 감싸 돌므로
// 작은 검정 덩이(눈·코) 둘레에 털과 눈 사이 회갈색 획이 고리로 남는다(작은 흰 점 — 눈송이·전구 — 둘레도 같은 까닭으로 짙은 테, 11/03). 덩이 지도(FS_BLOB)를 붓 크기만큼 넓힌 자리에서만
// 원본이 밝은 곳(털)은 원본 색으로, 원본이 어두운 곳(눈 안)은 원본보다 밝게 칠한 회색만 원본으로 되돌린다 — 눈 안의 획·하이라이트와
// 물감 요철(아래 높이 음영)은 그대로. 다른 자리는 화소 하나 바뀌지 않는다
if (uEyeK > 0.) {
  vec2 tv = uEyeR/vec2(textureSize(uGrade, 0));
  float bw = blb(uv);
  for (int i = 0; i < 8; i++) { vec2 d = vec2(cos(float(i)*.7854), sin(float(i)*.7854))*tv;
    bw = max(bw, max(.95*blb(uv + d*8.), .7*blb(uv + d*16.))); }
  vec3 sg = textureLod(uGrade, uv, 0.).rgb;
  float og = smoothstep(.3, .6, max(sg.r, max(sg.g, sg.b)));
  og = max(og, (1. - og)*smoothstep(.06, .18, lum(c) - lum(sg)));
  c = mix(c, sg, uEyeK*bw*og);
  // 눈 둘레 잡티(11/02 재연 님 '눈 주위를 원형으로 둘러싼 잡티'): 짙은 점(눈)이 있으면 둘레 수십 px까지 '세밀한 곳'으로 판정돼 중간 · 가는 붓이
  // 몰리고, 털의 잔잔한 음영을 짧고 짙은 획으로 옮겨 그린다(영상에서는 그림마다 반짝여 테두리처럼 읽힘). 덩이 둘레 넓은 띠(붓 크기 × 10~70px)에서
  // 원본이 밝은 곳의 '원본보다 .04 넘게 짙은 칠'만 원본 쪽으로 — 붓결 · 물감 요철(아래)은 그대로
  float dk = smoothstep(.04, .12, lum(sg) - lum(c))*smoothstep(.3, .6, max(sg.r, max(sg.g, sg.b)));
  if (dk > 0.) {
    float bo = 0.;
    for (int i = 0; i < 8; i++) { vec2 d = vec2(cos(float(i)*.7854 + .39), sin(float(i)*.7854 + .39))*tv;
      for (int k = 1; k <= 7; k++) bo = max(bo, (1. - .09*float(k - 1))*blb(uv + d*10.*float(k))); }
    c = mix(c, sg, uEyeK*smoothstep(.2, .5, bo)*dk);
  }
}
// 경계 밖 잔획 정리(11/05 재연 님 '깨또 귀 끝 둘레 붉은 바탕에 검은 점 · 짧은 획', OIL.edge): 굵은 붓(굵기 약 50px · 흐린 원본 밉 3.8)이 센 경계 둘레에서
// 짙은 쪽 색을 집거나 폭만큼 경계 밖으로 넘쳐 칠하고, 뒤 층이 대부분 덮은 뒤 남은 조각이 바탕 위 점 · 짧은 획이 된다(획 경로를 경계에서 끊어도 폭으로 넘쳐 남음).
// 원본이 평평한 바탕(둘레 6 · 14px 여덟 방향 중 다섯 이상이 이 자리와 .03 안 — 경계 바로 바깥도 바탕 쪽 절반이 평평해 들어간다)에서
// 칠이 원본과 .07 넘게 다른 화소만 원본 쪽으로. 평평한 바탕의 붓결 색 차는 .05 안팎이라 그대로, 뜨개 · 털 · 체크처럼 무늬가 있는 곳과
// 경계 위(어느 쪽도 평평하지 않음)는 손대지 않는다(밉 2와 한 점만 비교하면 무늬 속 중간 톤도 평평으로 잡혀 붓결이 지워졌다). 물감 요철(아래)은 그대로
if (uEdgeK > 0.) {
  vec3 sg = textureLod(uGrade, uv, 0.).rgb, s1 = textureLod(uGrade, uv, 1.).rgb;
  vec2 tv = 6./vec2(textureSize(uGrade, 0));
  float nf = 0.;
  for (int i = 0; i < 8; i++) { vec2 d = vec2(cos(float(i)*.7854), sin(float(i)*.7854))*tv;
    nf += 1. - smoothstep(.03, .06, max(distance(textureLod(uGrade, uv + d, 1.).rgb, s1), distance(textureLod(uGrade, uv + d*2.3, 1.).rgb, s1))); }
  c = mix(c, sg, uEdgeK*smoothstep(4.5, 6., nf)*smoothstep(.07, .14, distance(c, sg)));
}
// 경계 둘레 테(11/05 메인 · 재연 님 — 흰 곰 실루엣 바로 바깥 약 10px '짙은 붉은 테', OIL.halo): 짙은 칠이 아니다. 굵은 붓이 경계의 섞인 색으로
// 원본보다 두 배쯤 넓은 분홍 · 장밋빛 띠(바탕보다 밝기 +2~+27, 원본 +2~+9)를 남기고, 그 사이에 낀 바탕색 줄이 짙은 테로 읽힌다(1px 단위 단면 · 4배로 확인,
// 물감 요철 · 광택 · 캔버스 결 · 층 끄기와 상관없음). 센 경계(둘레 24px 안에 .06~.12 넘는 색 차) 가까이에서만 칠의 흐린 평균을 원본의 흐린 평균에
// 맞춘다(±.08 안 — 그보다 큰 붓결 차는 남는다), 넓은 바탕 안쪽의 붓 얼룩은 그대로. 밉 1(2~3px). 밉 3으로 넓게 맞추면 칠 판(실제 크기)과 원본(가상 크기)의
// 흐림 모양이 달라 경계 9~12px 바깥이 바탕보다 어두워져(−3.6) 오히려 짙은 테가 생겼다. 영상 반짝임은 같거나 조금 준다
if (uHaloK > 0.) {
  vec3 s1 = textureLod(uGrade, uv, 1.).rgb; vec2 tv = 24./vec2(textureSize(uGrade, 0));
  float ne = 0.;
  for (int i = 0; i < 8; i++) ne = max(ne, smoothstep(.06, .12, distance(textureLod(uGrade, uv + vec2(cos(float(i)*.7854), sin(float(i)*.7854))*tv, 1.).rgb, s1)));
  float pl = 1. + log2(float(textureSize(uPaint, 0).x)/float(textureSize(uGrade, 0).x));   // 칠 판은 실제 크기, 원본은 가상 크기 — 같은 넓이로 흐리게
  c += uHaloK*ne*clamp(textureLod(uGrade, uv, 1.).rgb - textureLod(uPaint, uv, pl).rgb, -.08, .08);
}

port.blobFragment:
uniform sampler2D uTex;
float vmx(vec2 uv){ vec3 c = textureLod(uTex, uv, 2.).rgb; return max(c.r, max(c.g, c.b)); }
float lmb(vec2 uv){ return lum(textureLod(uTex, uv, 1.).rgb); }
void main(){
  vec2 ts = 1./vec2(textureSize(uTex, 0));
  float v = vmx(vUV), dk = 1. - smoothstep(.14, .3, v), sm = 0.;
  if (dk > 0.) for (int k = 0; k < 4; k++) { float R = k == 0 ? 20. : k == 1 ? 34. : k == 2 ? 52. : 80., n = 0.;
    for (int i = 0; i < 12; i++) { float a = float(i)*.5236 + float(k)*.13; n += step(v + .4, vmx(vUV + vec2(cos(a), sin(a))*R*ts)); }
    sm = max(sm, smoothstep(8.5, 10.5, n)); }
  float l = lmb(vUV), bk = smoothstep(.4, .52, l), sb = 0.;
  if (bk > 0.) for (int k = 0; k < 4; k++) { float R = k == 0 ? 8. : k == 1 ? 12. : k == 2 ? 20. : 34., n = 0.;
    for (int i = 0; i < 12; i++) { float a = float(i)*.5236 + float(k)*.13; n += step(lmb(vUV + vec2(cos(a), sin(a))*R*ts) + .16, l); }
    sb = max(sb, smoothstep(8.5, 10.5, n)); }
  o = vec4(dk*sm, bk*sb, 0., 0.);
}
